// Watchtower's report template renders each failure as two lines:
//   ❌ <container> — <image>
//      Failed: <error>
// Only transient registry/network errors are retried; anything else
// (bad tag, missing image, container create errors) would just fail again.
const raw = $input.first().json.body;
const body = typeof raw === 'string' ? raw : (raw?.message ?? '');

let host = null;
if (/dmz-host/.test(body)) host = 'dmz';
else if (/internal-host/.test(body)) host = 'internal';
if (!host) return [];

const RETRYABLE = /rate limit|toomanyrequests|\b429\b|TLS handshake timeout|i\/o timeout|connection reset|context deadline exceeded|unexpected EOF|Client\.Timeout/i;
// The webhook is unauthenticated and names end up in a shell command, so
// accept only what Docker itself allows in a container name.
const SAFE_NAME = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;

const lines = body.split('\n');
const containers = [];
for (let i = 0; i < lines.length; i++) {
  const m = lines[i].match(/^❌ (\S+) — (\S+)/);
  if (!m || !SAFE_NAME.test(m[1])) continue;
  const error = (lines[i + 1] || '').trim();
  if (RETRYABLE.test(error) && !containers.some(c => c.name === m[1])) {
    containers.push({ name: m[1], image: m[2], error });
  }
}
if (!containers.length) return [];

return [{
  json: {
    host,
    hostLabel: host === 'dmz' ? 'dmz-host' : 'internal-host',
    namesArg: containers.map(c => c.name).join(' '),
    containers,
  },
}];

const src = $('Find Retryable Failures').first().json;
const stdout = ($json.stdout || '').trim();
const ok = stdout.includes('===RESULT:ok===');
const updated = /updated=([1-9]\d*)/.test(stdout);
const log = stdout.replace(/===RESULT:\w+===/g, '').trim().slice(-2500);

const head = ok
  ? (updated ? '🔁✅ Watchtower retry succeeded' : '🔁✅ Watchtower retry: already current')
  : '🔁❌ Watchtower retry failed — next scheduled run will try again';

const text = [
  `${head} — ${src.hostLabel}`,
  '',
  ...src.containers.map(c => `• ${c.name} — ${c.image}`),
  '',
  log || (stdout ? '' : `(no output; ssh stderr: ${($json.stderr || '').slice(-500)})`),
].join('\n');

return [{ json: { text } }];
